pub fn bin_search(a: &[i32], k: i32) -> bool {
    // We maintain a half-open interval [lo, hi)
    // such that if k is in `a`, it must lie at some index in [lo, hi).
    let mut lo = 0;
    let mut hi = a.len();

    while lo < hi {
        // Avoid overflow when computing the midpoint
        let mid = lo + (hi - lo) / 2;
        if a[mid] == k {
            return true;
        } else if a[mid] < k {
            // k, if present, must be in the right half (mid+1 .. hi)
            lo = mid + 1;
        } else {
            // k, if present, must be in the left half (lo .. mid)
            hi = mid;
        }
    }

    // If we exit the loop, the interval is empty and k wasn't found
    false
}